using FolderVerse;
using System.Text.Json;
var raw=AutoSaveStore.Read<object>(args[0]);var w=raw is WorldSetup d?d:(WorldSetup)raw.GetType().GetProperty("World")!.GetValue(raw)!;
var c=w.Campaign.RobotBattles;foreach(var b in c.Encounters.SelectMany(e=>e.Battles))b.Allied=w.Relations.Allied;
void Report(string stage){var h=w.Nodes.Current(8);Console.WriteLine(JsonSerializer.Serialize(new{stage,turn=w.Population.Turn,home=h.Id,root=w.Relations.Root(8),pocket=w.Robots.Retinues[8].Robots.Select(r=>new{r.Id,r.Owner,r.Parts,r.CanFight,eligible=w.Robots.Training[8].Eligible(r)}),selectable=c.SelectableRobots(w,8,h.Id,true).Select(r=>r.Id),targets=new[]{129,130}.Select(t=>new{target=t,owner=w.Nodes.All[t].Owner,can=c.CanSortie(w,8,t),defense=c.DefendingRobots(w,8,t),locked=c.LockedNode(t),defenderHome=w.Nodes.All[t].Owner>=0?w.Nodes.Current(w.Nodes.All[t].Owner)?.Id:null,defenderPocket=w.Nodes.All[t].Owner>=0?w.Robots.Retinues[w.Nodes.All[t].Owner].Robots.Select(r=>new{r.Id,r.Owner,r.CanFight,eligible=w.Robots.Training[r.Owner].Eligible(r)}):null,stock=w.Robots.Nodes[t].Robots.Select(r=>new{r.Id,r.Owner,r.CanFight,r.DefenseOnly})}),queenBattles=c.Encounters.Where(e=>!e.Finished).SelectMany(e=>e.Battles.Select(b=>new{e.Target,b.Id,queens=b.Units.Where(u=>u.Owner==8 && u.Role==BattleRole.Queen).Select(u=>new{u.Id,u.Fallen,u.Retreated})})).Where(b=>b.queens.Any())}));}
Report("saved");w.Robots.PrepareDomestic(w.Population.Turn,(a,b)=>FunctionalDeliveryRoutes.Connected(w,a,b),n=>w.Nodes.All[n].Owner,c.LockedNode);Report("prepared");
foreach(var board in c.Encounters.Where(e=>e.Target==127).SelectMany(e=>e.Battles))Console.WriteLine(JsonSerializer.Serialize(new{stage="battle-settings",board.Id,board.GlobalTurn,lessons=board.Lessons.Select((v,i)=>new{owner=i,bits=(int)v}).Where(x=>x.owner==8 || x.owner==10),rules=board.Rules,board.NewspaperRanks,armies=board.Armies.Select(a=>new{a.Owner,a.HomeNode,a.Side,a.EntrySlot,a.Limit,a.InvadingQueen,a.Wanderer,policy=a.WandererPolicy.ToString()}),wallDirections=board.WallShotDirections.OrderBy(p=>p.Key.X).ThenBy(p=>p.Key.Y).Select(p=>new{p.Key.X,p.Key.Y,p.Value})}));